&lt;span class="field field--name-title field--type-string field--label-hidden"&gt;Milán se mueve desde la Torre de Niza&lt;/span&gt;
&lt;span class="field field--name-uid field--type-entity-reference field--label-hidden"&gt;&lt;span lang="" about="/user/59" typeof="schema:Person" property="schema:name" datatype=""&gt;Alejandro Calderin&lt;/span&gt;&lt;/span&gt;
